module iddr_sweep(input clk, input c0, input c1, input c2, input c3, output reg r, input p0, input p1, input p2, input p3, input p4, input p5, input p6, input p7, input p8, input p9, input p10, input p11, input p12, input p13, input p14, input p15, input p16, input p17, input p18, input p19, input p20, input p21, input p22, input p23, input p24, input p25);
  wire gclk; BUFG bg(.I(clk), .O(gclk));
  wire q1_0, q2_0;
  IDDR u0(.Q1(q1_0), .Q2(q2_0), .C(gclk), .CE(c0), .D(p0), .R(1'b0), .S(1'b0));
  wire q1_1, q2_1;
  IDDR #(.DDR_CLK_EDGE("SAME_EDGE")) u1(.Q1(q1_1), .Q2(q2_1), .C(gclk), .CE(c0), .D(p1), .R(1'b0), .S(1'b0));
  wire q1_2, q2_2;
  IDDR #(.DDR_CLK_EDGE("SAME_EDGE_PIPELINED")) u2(.Q1(q1_2), .Q2(q2_2), .C(gclk), .CE(c0), .D(p2), .R(1'b0), .S(1'b0));
  wire q1_3, q2_3;
  IDDR #(.SRTYPE("ASYNC")) u3(.Q1(q1_3), .Q2(q2_3), .C(gclk), .CE(c0), .D(p3), .R(1'b0), .S(1'b0));
  wire q1_4, q2_4;
  IDDR #(.INIT_Q1(1'b1)) u4(.Q1(q1_4), .Q2(q2_4), .C(gclk), .CE(c0), .D(p4), .R(1'b0), .S(1'b0));
  wire q1_5, q2_5;
  IDDR #(.INIT_Q2(1'b1)) u5(.Q1(q1_5), .Q2(q2_5), .C(gclk), .CE(c0), .D(p5), .R(1'b0), .S(1'b0));
  wire q1_6, q2_6;
  IDDR #(.IS_C_INVERTED(1'b1)) u6(.Q1(q1_6), .Q2(q2_6), .C(gclk), .CE(c0), .D(p6), .R(1'b0), .S(1'b0));
  wire q1_7, q2_7;
  IDDR #(.IS_D_INVERTED(1'b1)) u7(.Q1(q1_7), .Q2(q2_7), .C(gclk), .CE(c0), .D(p7), .R(1'b0), .S(1'b0));
  wire q1_8, q2_8;
  IDDR u8(.Q1(q1_8), .Q2(q2_8), .C(gclk), .CE(c0), .D(p8), .R(c1), .S(1'b0));
  wire q1_9, q2_9;
  IDDR u9(.Q1(q1_9), .Q2(q2_9), .C(gclk), .CE(c0), .D(p9), .R(1'b0), .S(c1));
  wire q1_10, q2_10;
  IDDR #(.SRTYPE("ASYNC")) u10(.Q1(q1_10), .Q2(q2_10), .C(gclk), .CE(c0), .D(p10), .R(c1), .S(1'b0));
  wire q1_11, q2_11;
  IDDR #(.SRTYPE("ASYNC")) u11(.Q1(q1_11), .Q2(q2_11), .C(gclk), .CE(c0), .D(p11), .R(1'b0), .S(c1));
  wire q1_12, q2_12;
  IDDR #(.INIT_Q1(1'b1),.INIT_Q2(1'b1)) u12(.Q1(q1_12), .Q2(q2_12), .C(gclk), .CE(c0), .D(p12), .R(c1), .S(1'b0));
  wire q1_13, q2_13;
  IDDR #(.INIT_Q1(1'b1)) u13(.Q1(q1_13), .Q2(q2_13), .C(gclk), .CE(c0), .D(p13), .R(1'b0), .S(c1));
  wire q1_14, q2_14;
  IDDR u14(.Q1(q1_14), .Q2(q2_14), .C(gclk), .CE(c0), .D(p14), .R(1'b1), .S(1'b0));
  wire q1_15, q2_15;
  IDDR u15(.Q1(q1_15), .Q2(q2_15), .C(gclk), .CE(c0), .D(p15), .R(1'b0), .S(1'b1));
  wire q1_16, q2_16;
  IDDR u16(.Q1(q1_16), .Q2(q2_16), .C(gclk), .CE(1'b1), .D(p16), .R(1'b0), .S(1'b0));
  wire q1_17, q2_17;
  IDDR u17(.Q1(q1_17), .Q2(q2_17), .C(gclk), .CE(1'b0), .D(p17), .R(1'b0), .S(1'b0));
  wire q1_18, q2_18;
  IDDR u18(.Q1(q1_18), .Q2(q2_18), .C(gclk), .CE(c0), .D(p18), .R(1'b0), .S(1'b0));
  wire q1_19, q2_19;
  IDDR #(.DDR_CLK_EDGE("SAME_EDGE"),.INIT_Q1(1'b1)) u19(.Q1(q1_19), .Q2(q2_19), .C(gclk), .CE(c0), .D(p19), .R(1'b0), .S(1'b0));
  wire q1_20, q2_20;
  IDDR #(.DDR_CLK_EDGE("SAME_EDGE"),.INIT_Q2(1'b1)) u20(.Q1(q1_20), .Q2(q2_20), .C(gclk), .CE(c0), .D(p20), .R(1'b0), .S(1'b0));
  wire q1_21, q2_21;
  IDDR #(.DDR_CLK_EDGE("SAME_EDGE")) u21(.Q1(q1_21), .Q2(q2_21), .C(gclk), .CE(c0), .D(p21), .R(c1), .S(1'b0));
  wire q1_22, q2_22;
  IDDR #(.DDR_CLK_EDGE("SAME_EDGE_PIPELINED"),.INIT_Q1(1'b1)) u22(.Q1(q1_22), .Q2(q2_22), .C(gclk), .CE(c0), .D(p22), .R(1'b0), .S(1'b0));
  wire q1_23, q2_23;
  IDDR #(.DDR_CLK_EDGE("SAME_EDGE_PIPELINED"),.INIT_Q2(1'b1)) u23(.Q1(q1_23), .Q2(q2_23), .C(gclk), .CE(c0), .D(p23), .R(1'b0), .S(1'b0));
  wire q1_24, q2_24;
  IDDR #(.DDR_CLK_EDGE("SAME_EDGE_PIPELINED")) u24(.Q1(q1_24), .Q2(q2_24), .C(gclk), .CE(c0), .D(p24), .R(c1), .S(1'b0));
  wire q1_25, q2_25;
  IDDR #(.DDR_CLK_EDGE("SAME_EDGE"),.IS_C_INVERTED(1'b1)) u25(.Q1(q1_25), .Q2(q2_25), .C(gclk), .CE(c0), .D(p25), .R(1'b0), .S(1'b0));
  always @(posedge gclk) r <= q1_0 ^ q2_0 ^ q1_1 ^ q2_1 ^ q1_2 ^ q2_2 ^ q1_3 ^ q2_3 ^ q1_4 ^ q2_4 ^ q1_5 ^ q2_5 ^ q1_6 ^ q2_6 ^ q1_7 ^ q2_7 ^ q1_8 ^ q2_8 ^ q1_9 ^ q2_9 ^ q1_10 ^ q2_10 ^ q1_11 ^ q2_11 ^ q1_12 ^ q2_12 ^ q1_13 ^ q2_13 ^ q1_14 ^ q2_14 ^ q1_15 ^ q2_15 ^ q1_16 ^ q2_16 ^ q1_17 ^ q2_17 ^ q1_18 ^ q2_18 ^ q1_19 ^ q2_19 ^ q1_20 ^ q2_20 ^ q1_21 ^ q2_21 ^ q1_22 ^ q2_22 ^ q1_23 ^ q2_23 ^ q1_24 ^ q2_24 ^ q1_25 ^ q2_25;
endmodule
